620	 /* Xe đang ở ô hầm không: ô chứa (x, z) có cao độ gần y nhất trong ± stepMax (như drive/net.ts drPadAt), kiểu 'tunnel'. Duyệt tuyến tính, không cấp phát */
621	 function bkInTunnel(n: DrNet, s: BkState): boolean {
622	   const step = CONFIG.drive.stepMax;
623	   let best = -1, bestD = Infinity;
624	   for (let i = 0; i < n.pads.length; i++) {
625	     const p = n.pads[i];
626	     if (s.x < p.x0 || s.x > p.x1 || s.z < p.z0 || s.z > p.z1 || (p.gate !== undefined && n.closed.has(p.gate))) continue;
627	     const d = Math.abs(p.y(s.x, s.z) - s.y);
628	     if (d <= step && d < bestD) { best = i; bestD = d; }
629	   }
630	   return best >= 0 && n.pads[best].kind === 'tunnel';
631	 }
